import ColumnHeader from './data-table-column-header.svelte';
import DateFilter from './data-table-date-filter.svelte';
import FacetedFilter from './data-table-faceted-filter.svelte';
import FlexRender from './data-table-flex-render.svelte';
import Pagination from './data-table-pagination.svelte';
import Skeleton from './data-table-skeleton.svelte';
import SliderFilter from './data-table-slider-filter.svelte';
import Toolbar from './data-table-toolbar.svelte';
import ToolbarFilter from './data-table-toolbar-filter.svelte';
import ViewOptions from './data-table-view-options.svelte';
import Root from './data-table.svelte';

export type { DataTableRootProps } from './data-table.svelte';
export type { DataTableFlexRenderProps, DataTableTemplate } from './data-table-flex-render.svelte';
export type { DataTableColumnHeaderProps } from './data-table-column-header.svelte';
export type { DataTableToolbarProps } from './data-table-toolbar.svelte';
export type { DataTableToolbarFilterProps } from './data-table-toolbar-filter.svelte';
export type { DataTableFacetedFilterProps } from './data-table-faceted-filter.svelte';
export type { DataTableDateFilterProps } from './data-table-date-filter.svelte';
export type { DataTableSliderFilterProps } from './data-table-slider-filter.svelte';
export type { DataTableViewOptionsProps } from './data-table-view-options.svelte';
export type { DataTablePaginationProps } from './data-table-pagination.svelte';
export type { DataTableSkeletonProps } from './data-table-skeleton.svelte';

export {
	DataTableInstance,
	DataTableState,
	createDataTable,
	getDataTableContext,
	hasDataTableContext,
	setDataTableContext,
	useDataTableInstance,
	type DataTableContext
} from './data-table.svelte.js';

export { dataTableConfig, type DataTableConfig } from './data-table-config.js';

export {
	formatDate,
	fromDateValue,
	getColumnPinningStyle,
	getDefaultFilterOperator,
	getFilterOperators,
	getIsDateRange,
	getIsValidRange,
	getSliderRange,
	getValidFilters,
	parseAsDate,
	parseColumnFilterValue,
	parseValuesAsNumbers,
	toDateValue,
	type DateRangeValue,
	type RangeValue
} from './data-table-utils.js';

export type {
	CreateDataTableOptions,
	DataTableColumnDef,
	DataTableColumnTemplate,
	DataTableIcon,
	DataTableInitialState,
	DataTableRowAction,
	ExtendedColumnFilter,
	ExtendedColumnSort,
	FilterOperator,
	FilterVariant,
	JoinOperator,
	Option,
	QueryKeys
} from './types.js';

export {
	Root,
	FlexRender,
	ColumnHeader,
	Toolbar,
	ToolbarFilter,
	FacetedFilter,
	DateFilter,
	SliderFilter,
	ViewOptions,
	Pagination,
	Skeleton,
	//
	Root as DataTable,
	FlexRender as DataTableFlexRender,
	ColumnHeader as DataTableColumnHeader,
	Toolbar as DataTableToolbar,
	ToolbarFilter as DataTableToolbarFilter,
	FacetedFilter as DataTableFacetedFilter,
	DateFilter as DataTableDateFilter,
	SliderFilter as DataTableSliderFilter,
	ViewOptions as DataTableViewOptions,
	Pagination as DataTablePagination,
	Skeleton as DataTableSkeleton
};

import type {
	CellContext,
	ColumnDef,
	ColumnFiltersState,
	ColumnOrderState,
	ColumnPinningState,
	ColumnSort,
	HeaderContext,
	InitialTableState,
	PaginationState,
	Row,
	RowData,
	RowSelectionState,
	SortingState,
	TableOptions,
	TableState,
	VisibilityState
} from '@tanstack/table-core';
import type { Component, Snippet } from 'svelte';
import type { HTMLAttributes } from 'svelte/elements';

import type { WithoutChildren } from '$UTILS$.js';

import type { DataTableConfig } from './data-table-config.js';

/**
 * The attribute surface a filter part spreads onto the control it renders.
 *
 * Two attributes are dropped from `HTMLAttributes` rather than forwarded: `title`, because it is a
 * *prop* of every filter part (the trigger's label) and would otherwise collide, and `id`, which
 * `svelte/elements` types `string | null` where the bits-ui primitives underneath accept only
 * `string | undefined` — so it is re-declared narrowly instead.
 */
export type DataTableFilterAttributes = Omit<
	WithoutChildren<HTMLAttributes<HTMLElement>>,
	'id' | 'title'
> & {
	id?: string;
};

/**
 * An icon component — a `@lucide/svelte` icon, or any Svelte component that renders an `<svg>`.
 *
 * Upstream types this `React.FC<React.SVGProps<SVGSVGElement>>`. Typing it against Svelte's
 * `SVGAttributes` would *reject* every `@lucide/svelte` icon, because Svelte's SVG attribute types
 * allow `null` where lucide's own props do not. Requiring only `class` accepts both and is all the
 * component set ever passes.
 */
export type DataTableIcon = Component<{ class?: string }>;

/**
 * `label` / `variant` / `options` / `range` / `unit` / `icon` / `placeholder` on a column's `meta`
 * are what every toolbar surface reads. Augmenting `@tanstack/table-core` (rather than
 * `@tanstack/react-table`, which this port does not depend on) makes the fields visible on
 * `column.columnDef.meta` everywhere, exactly as upstream's `docs/types/data-table.ts` does.
 */
declare module '@tanstack/table-core' {
	interface TableMeta<TData extends RowData> {
		/**
		 * Upstream persists table state to the URL with `nuqs` and threads the query-string keys
		 * through here. This port owns its state instead (plan.md Divergence 2), so nothing reads
		 * this field; it is retained so consumer code and the out-of-scope advanced filter
		 * components keep type-checking.
		 */
		queryKeys?: QueryKeys;
		/**
		 * Never assigned, never read. An interface augmentation must repeat the upstream type
		 * parameter list *verbatim* (TS2428), and neither field above is generic — upstream
		 * silences the resulting "unused type parameter" with a `biome-ignore`, which this repo's
		 * zero-suppression rule forbids, so the parameter is spent on a phantom member instead.
		 */
		readonly _phantomRow?: (row: TData) => never;
	}

	interface ColumnMeta<TData extends RowData, TValue> {
		/** Human label for the column — header text, filter title and the View list entry. */
		label?: string;
		/** Placeholder for the `text` / `number` filter inputs. Falls back to {@link label}. */
		placeholder?: string;
		/** Which filter control the toolbar renders. Absent ⇒ no control at all. */
		variant?: FilterVariant;
		/** Options for the `select` / `multiSelect` variants. */
		options?: Option[];
		/** `[min, max]` bounds for the `range` variant, overriding the faceted min/max. */
		range?: [number, number];
		/** Unit suffix rendered inside the `number` and `range` controls, e.g. `"hrs"`. */
		unit?: string;
		/** Icon rendered beside the column, as a Svelte component. */
		icon?: DataTableIcon;
		/** Never assigned, never read — see `TableMeta._phantomRow` above. */
		readonly _phantomCell?: (row: TData, value: TValue) => never;
	}
}

/**
 * The five query-string keys upstream's `nuqs` integration used. Retained for API-shape parity
 * (plan.md Divergence 5) — nothing in this port reads them.
 */
export interface QueryKeys {
	page: string;
	perPage: string;
	sort: string;
	filters: string;
	joinOperator: string;
}

/** One selectable value of a `select` / `multiSelect` column filter. */
export interface Option {
	/** Rendered text, and what the trigger badge shows. */
	label: string;
	/** What lands in `columnFilters[].value`. */
	value: string;
	/** Occurrence count, right-aligned in the list. Rendered only when truthy. */
	count?: number;
	/** Optional leading icon. */
	icon?: DataTableIcon;
}

/** `text | number | range | date | dateRange | boolean | select | multiSelect`. */
export type FilterVariant = DataTableConfig['filterVariants'][number];

/** Every comparison operator the (out-of-scope) advanced filter surfaces offer. */
export type FilterOperator = DataTableConfig['operators'][number];

/** How multiple advanced filters combine: `and` or `or`. */
export type JoinOperator = DataTableConfig['joinOperators'][number];

/**
 * A column template. React's `flexRender()` accepts a component or a string; the Svelte
 * equivalent is a string or a {@link Snippet} rendered by `DataTable.FlexRender`
 * (plan.md Divergence 13).
 */
export type DataTableColumnTemplate<TContext extends object> = string | Snippet<[TContext]>;

/**
 * `@tanstack/table-core`'s `ColumnDef` with `header` and `cell` narrowed to a string or a Svelte
 * snippet. The intersection keeps every discriminated member of the upstream union — so
 * `accessorKey`, `accessorFn`, `id` and `columns` behave exactly as they do upstream — while
 * making the template fields read back as something `DataTable.FlexRender` can `{@render}`.
 */
export type DataTableColumnDef<TData extends RowData, TValue = unknown> = ColumnDef<
	TData,
	TValue
> & {
	/** Header template. Absent ⇒ `DataTable.FlexRender` falls back to `column.id`. */
	header?: DataTableColumnTemplate<HeaderContext<TData, TValue>>;
	/** Cell template. Absent ⇒ falls back to the stringified cell value. */
	cell?: DataTableColumnTemplate<CellContext<TData, TValue>>;
};

/** A sort entry whose `id` is constrained to a key of the row type. */
export interface ExtendedColumnSort<TData> extends Omit<ColumnSort, 'id'> {
	id: Extract<keyof TData, string>;
}

/**
 * One advanced-filter entry. Upstream extends a Zod `FilterItemSchema` from `lib/parsers.ts`,
 * which is not vendored at the pinned commit; the fields are inlined here so no new dependency
 * is introduced (data-model.md §5).
 */
export interface ExtendedColumnFilter<TData> {
	id: Extract<keyof TData, string>;
	value: string | string[];
	variant: FilterVariant;
	operator: FilterOperator;
	filterId: string;
}

/** A row-level action a consumer's cell template dispatches, e.g. from a row dropdown. */
export interface DataTableRowAction<TData> {
	row: Row<TData>;
	variant: 'update' | 'delete';
}

/** `InitialTableState` with `sorting` constrained to keys of the row type. */
export type DataTableInitialState<TData> = Omit<InitialTableState, 'sorting'> & {
	sorting?: ExtendedColumnSort<TData>[];
};

/**
 * Options accepted by `createDataTable`. Everything `@tanstack/table-core`'s `TableOptions`
 * offers is available except the members this port owns: the row models, the seven state slices'
 * change handlers, `state`, `initialState`, `data`, `columns` and `pageCount` are all re-declared
 * below, and `onStateChange` / `renderFallbackValue` are supplied internally.
 *
 * Upstream's nuqs-only options (`queryKeys`, `history`, `debounceMs`, `throttleMs`,
 * `clearOnDefault`, `scroll`, `shallow`, `startTransition`, `enableAdvancedFilter`) are dropped —
 * plan.md Divergence 5.
 */
export type CreateDataTableOptions<TData extends RowData> = Omit<
	TableOptions<TData>,
	| 'columns'
	| 'data'
	| 'defaultColumn'
	| 'getCoreRowModel'
	| 'getFacetedMinMaxValues'
	| 'getFacetedRowModel'
	| 'getFacetedUniqueValues'
	| 'getFilteredRowModel'
	| 'getPaginationRowModel'
	| 'getSortedRowModel'
	| 'initialState'
	| 'onColumnFiltersChange'
	| 'onColumnOrderChange'
	| 'onColumnPinningChange'
	| 'onColumnVisibilityChange'
	| 'onPaginationChange'
	| 'onRowSelectionChange'
	| 'onSortingChange'
	| 'onStateChange'
	| 'pageCount'
	| 'renderFallbackValue'
	| 'state'
> & {
	/** The rows. Pass a getter to keep them reactive. */
	data: TData[] | (() => TData[]);
	/** The column definitions. Pass a getter to keep them reactive. */
	columns: DataTableColumnDef<TData>[] | (() => DataTableColumnDef<TData>[]);
	/**
	 * Total page count for server-driven pagination. `-1` lets `table-core` derive it.
	 * @default -1
	 */
	pageCount?: number;
	/** Seeds the seven state slices. `sorting` is typed against the row's keys. */
	initialState?: DataTableInitialState<TData>;
	/**
	 * Fully controlled state, merged over the internal slices. Pass a getter to keep it reactive.
	 */
	state?: Partial<TableState> | (() => Partial<TableState>);
	/**
	 * Defaults merged into every column definition. `enableColumnFilter` is forced to `false`
	 * afterwards, matching upstream.
	 */
	defaultColumn?: Partial<DataTableColumnDef<TData>>;
	/** Called with the resolved next sorting state. */
	onSortingChange?: (sorting: SortingState) => void;
	/** Called with the resolved next column-filter state. */
	onColumnFiltersChange?: (columnFilters: ColumnFiltersState) => void;
	/** Called with the resolved next pagination state. */
	onPaginationChange?: (pagination: PaginationState) => void;
	/** Called with the resolved next row-selection state. */
	onRowSelectionChange?: (rowSelection: RowSelectionState) => void;
	/** Called with the resolved next column-visibility state. */
	onColumnVisibilityChange?: (columnVisibility: VisibilityState) => void;
	/** Called with the resolved next column-pinning state. */
	onColumnPinningChange?: (columnPinning: ColumnPinningState) => void;
	/** Called with the resolved next column-order state. */
	onColumnOrderChange?: (columnOrder: ColumnOrderState) => void;
};

import { CalendarDate, getLocalTimeZone, type DateValue } from '@internationalized/date';
import type { Column, RowData } from '@tanstack/table-core';

import { dataTableConfig } from './data-table-config.js';
import type { ExtendedColumnFilter, FilterOperator, FilterVariant } from './types.js';

/**
 * Inline `style` for a (possibly pinned) header or body cell.
 *
 * Ported from upstream `docs/lib/data-table.ts`, which computes the same values in JS because the
 * sticky offsets depend on the runtime widths of the preceding pinned columns and cannot be
 * expressed as utility classes. React takes a style *object*; Svelte's `style` attribute takes a
 * string, so this returns CSS text (research D-08). The `z-index: 1` is upstream's own value and
 * lands on a `<th>`/`<td>`, not on an overlay.
 *
 * @param withBorder Draw upstream's inset shadow on the last left-pinned / first right-pinned
 * column. @default false
 */
export function getColumnPinningStyle<TData extends RowData>({
	column,
	withBorder = false
}: {
	column: Column<TData, unknown>;
	withBorder?: boolean;
}): string {
	const isPinned = column.getIsPinned();
	const isLastLeftPinnedColumn = isPinned === 'left' && column.getIsLastColumn('left');
	const isFirstRightPinnedColumn = isPinned === 'right' && column.getIsFirstColumn('right');

	const declarations: string[] = [];

	if (withBorder && isLastLeftPinnedColumn) {
		declarations.push('box-shadow: -4px 0 4px -4px var(--border) inset');
	} else if (withBorder && isFirstRightPinnedColumn) {
		declarations.push('box-shadow: 4px 0 4px -4px var(--border) inset');
	}
	if (isPinned === 'left') {
		declarations.push(`left: ${column.getStart('left')}px`);
	}
	if (isPinned === 'right') {
		declarations.push(`right: ${column.getAfter('right')}px`);
	}
	declarations.push(`opacity: ${isPinned ? 0.97 : 1}`);
	declarations.push(`position: ${isPinned ? 'sticky' : 'relative'}`);
	declarations.push('background: var(--background)');
	declarations.push(`width: ${column.getSize()}px`);
	if (isPinned) {
		declarations.push('z-index: 1');
	}

	return `${declarations.join('; ')};`;
}

/** Every operator offered for a filter variant. Unknown variants fall back to the text operators. */
export function getFilterOperators(
	filterVariant: FilterVariant
): { label: string; value: FilterOperator }[] {
	const operatorMap: Record<FilterVariant, { label: string; value: FilterOperator }[]> = {
		text: dataTableConfig.textOperators,
		number: dataTableConfig.numericOperators,
		range: dataTableConfig.numericOperators,
		date: dataTableConfig.dateOperators,
		dateRange: dataTableConfig.dateOperators,
		boolean: dataTableConfig.booleanOperators,
		select: dataTableConfig.selectOperators,
		multiSelect: dataTableConfig.multiSelectOperators
	};

	return operatorMap[filterVariant] ?? dataTableConfig.textOperators;
}

/** The operator a freshly created filter of this variant starts with. */
export function getDefaultFilterOperator(filterVariant: FilterVariant): FilterOperator {
	const operators = getFilterOperators(filterVariant);

	return operators[0]?.value ?? (filterVariant === 'text' ? 'iLike' : 'eq');
}

/** Drops advanced filters that carry no value, unless the operator does not need one. */
export function getValidFilters<TData>(
	filters: ExtendedColumnFilter<TData>[]
): ExtendedColumnFilter<TData>[] {
	return filters.filter(
		(filter) =>
			filter.operator === 'isEmpty' ||
			filter.operator === 'isNotEmpty' ||
			(Array.isArray(filter.value)
				? filter.value.length > 0
				: filter.value !== '' && filter.value !== null && filter.value !== undefined)
	);
}

/**
 * `"January 1, 2024"`. Ported verbatim from upstream `docs/lib/format.ts` so trigger labels match
 * character for character; invalid input yields an empty string.
 */
export function formatDate(
	date: Date | string | number | undefined,
	opts: Intl.DateTimeFormatOptions = {}
): string {
	if (!date) return '';

	try {
		return new Intl.DateTimeFormat('en-US', {
			month: opts.month ?? 'long',
			day: opts.day ?? 'numeric',
			year: opts.year ?? 'numeric',
			...opts
		}).format(new Date(date));
	} catch {
		return '';
	}
}

/** Epoch milliseconds (or their string form) to a `Date`, or `undefined` when unparseable. */
export function parseAsDate(timestamp: number | string | undefined): Date | undefined {
	if (!timestamp) return undefined;
	const numericTimestamp = typeof timestamp === 'string' ? Number(timestamp) : timestamp;
	const date = new Date(numericTimestamp);
	return !Number.isNaN(date.getTime()) ? date : undefined;
}

/** Normalises whatever a date column's filter value happens to be into a timestamp list. */
export function parseColumnFilterValue(value: unknown): (number | string | undefined)[] {
	if (value === null || value === undefined) {
		return [];
	}

	if (Array.isArray(value)) {
		return value.map((item) => {
			if (typeof item === 'number' || typeof item === 'string') {
				return item;
			}
			return undefined;
		});
	}

	if (typeof value === 'string' || typeof value === 'number') {
		return [value];
	}

	return [];
}

/**
 * The `{ start, end }` pair the range calendar binds to. Structurally identical to bits-ui's
 * `DateRange`; upstream's `react-day-picker` calls the same thing `{ from, to }`.
 */
export type DateRangeValue = { start: DateValue | undefined; end: DateValue | undefined };

/** Distinguishes the range calendar's `{ start, end }` object from single mode's date list. */
export function getIsDateRange(value: DateValue[] | DateRangeValue): value is DateRangeValue {
	return typeof value === 'object' && !Array.isArray(value);
}

/**
 * Epoch milliseconds to the `@internationalized/date` value the local calendar wrapper binds to.
 * The *column filter* value stays epoch milliseconds — only the calendar speaks `DateValue`
 * (research D-05, plan.md Divergence 11).
 */
export function toDateValue(timestamp: number | string | undefined): CalendarDate | undefined {
	const date = parseAsDate(timestamp);
	if (!date) return undefined;
	return new CalendarDate(date.getFullYear(), date.getMonth() + 1, date.getDate());
}

/** The inverse of {@link toDateValue}: a calendar value back to epoch milliseconds. */
export function fromDateValue(value: DateValue | undefined): number | undefined {
	if (!value) return undefined;
	return value.toDate(getLocalTimeZone()).getTime();
}

/** A `[min, max]` numeric range, as stored in a `range` column's filter value. */
export type RangeValue = [number, number];

/** Whether an unknown value is a `[number, number]` tuple. */
export function getIsValidRange(value: unknown): value is RangeValue {
	return (
		Array.isArray(value) &&
		value.length === 2 &&
		typeof value[0] === 'number' &&
		typeof value[1] === 'number'
	);
}

/** Coerces a two-element numeric-ish array to a `[number, number]` tuple. */
export function parseValuesAsNumbers(value: unknown): RangeValue | undefined {
	if (
		Array.isArray(value) &&
		value.length === 2 &&
		value.every((v) => (typeof v === 'string' || typeof v === 'number') && !Number.isNaN(Number(v)))
	) {
		return [Number(value[0]), Number(value[1])];
	}

	return undefined;
}

/**
 * Slider bounds and step for a `range` column: `meta.range` when it is a valid `[min, max]`,
 * otherwise the column's faceted min/max, otherwise `[0, 100]`. Step buckets are upstream's —
 * `size ≤ 20 → 1`, `size ≤ 100 → ceil(size / 20)`, else `ceil(size / 50)`.
 */
export function getSliderRange(
	defaultRange: [number, number] | undefined,
	facetedMinMaxValues: undefined | [number, number]
): { min: number; max: number; step: number } {
	let minValue = 0;
	let maxValue = 100;

	if (defaultRange && getIsValidRange(defaultRange)) {
		[minValue, maxValue] = defaultRange;
	} else if (facetedMinMaxValues && getIsValidRange(facetedMinMaxValues)) {
		[minValue, maxValue] = facetedMinMaxValues;
	}

	const rangeSize = maxValue - minValue;
	const step =
		rangeSize <= 20 ? 1 : rangeSize <= 100 ? Math.ceil(rangeSize / 20) : Math.ceil(rangeSize / 50);

	return { min: minValue, max: maxValue, step };
}

import {
	createTable,
	functionalUpdate,
	getCoreRowModel,
	getFacetedMinMaxValues,
	getFacetedRowModel,
	getFacetedUniqueValues,
	getFilteredRowModel,
	getPaginationRowModel,
	getSortedRowModel,
	type ColumnFiltersState,
	type ColumnOrderState,
	type ColumnPinningState,
	type HeaderGroup,
	type PaginationState,
	type Row,
	type RowData,
	type RowSelectionState,
	type SortingState,
	type Table,
	type TableOptionsResolved,
	type TableState,
	type Updater,
	type VisibilityState
} from '@tanstack/table-core';
import { getContext, hasContext, setContext } from 'svelte';

import type { CreateDataTableOptions, DataTableColumnDef } from './types.js';

/**
 * The runes half of `@tanstack/table-core` — the replacement for upstream's `useDataTable`
 * (and, underneath it, `useReactTable`).
 *
 * The table instance is created **once** and never re-created. Reactivity flows through
 * `table.options`: `data`, `columns` and `state` are redefined as getter properties that read the
 * `$state.raw` slices below, so every `table.getRowModel()` / `column.getIsSorted()` /
 * `table.getState()` call made inside a template or a `$derived` registers a fine-grained
 * dependency and re-runs when the slice it touched changes (research D-02).
 *
 * The getters have to be installed *after* `createTable`, because `createTable` merges the options
 * object it is handed with `{ ...defaultOptions, ...options }` — a spread evaluates getters and
 * copies their values, which would freeze the bridge at its initial state.
 */
export class DataTableState<TData extends RowData> {
	// The `$derived` fields below are lazy at runtime (evaluated on first read, by which point the
	// constructor has run), but svelte-check's static analysis cannot see that across the
	// constructor assignment — hence the definite-assignment assertion, matching the pattern in
	// `direction-provider.svelte.ts`.
	#options!: CreateDataTableOptions<TData>;

	/**
	 * The slices this class does not own — `expanded`, `grouping`, `globalFilter`, `columnSizing`,
	 * `rowPinning` and friends. Seeded from `table.initialState` and updated through
	 * `onStateChange`, so a feature this port does not surface still behaves normally.
	 */
	#restState = $state.raw<Partial<TableState>>({});

	/** Current sorting. Writing it is the controlled path; it does not re-fire `onSortingChange`. */
	sorting = $state.raw<SortingState>([]);
	/** Current column filters. */
	columnFilters = $state.raw<ColumnFiltersState>([]);
	/** Which columns are hidden. */
	columnVisibility = $state.raw<VisibilityState>({});
	/** Selected rows, keyed by row id. */
	rowSelection = $state.raw<RowSelectionState>({});
	/** Current page index and size. */
	pagination = $state.raw<PaginationState>({ pageIndex: 0, pageSize: 10 });
	/** Which columns are pinned left/right. */
	columnPinning = $state.raw<ColumnPinningState>({ left: [], right: [] });
	/** Explicit column order, when one has been set. */
	columnOrder = $state.raw<ColumnOrderState>([]);

	/**
	 * The table instance. Its identity is stable for the lifetime of this state object.
	 *
	 * Assigned in the constructor and read only from the lazy `$derived` fields below, which do not
	 * run at field-initialisation time — the assertion tells svelte-check the same.
	 */
	readonly table!: Table<TData>;

	/** `table.getRowModel().rows` — the rows of the current page. */
	readonly rows: Row<TData>[] = $derived(this.table.getRowModel().rows);
	/** `table.getHeaderGroups()`. */
	readonly headerGroups: HeaderGroup<TData>[] = $derived(this.table.getHeaderGroups());
	/** `table.getPageCount()`. */
	readonly pageCount: number = $derived(this.table.getPageCount());
	/** How many selected rows survive the current filters. */
	readonly selectedRowCount: number = $derived(
		this.table.getFilteredSelectedRowModel().rows.length
	);
	/** How many rows survive the current filters. */
	readonly filteredRowCount: number = $derived(this.table.getFilteredRowModel().rows.length);
	/** Whether at least one column filter is applied. */
	readonly isFiltered: boolean = $derived(this.columnFilters.length > 0);

	constructor(options: CreateDataTableOptions<TData>) {
		this.#options = options;

		const {
			data: _data,
			columns: _columns,
			state: _state,
			onSortingChange: _onSortingChange,
			onColumnFiltersChange: _onColumnFiltersChange,
			onColumnVisibilityChange: _onColumnVisibilityChange,
			onRowSelectionChange: _onRowSelectionChange,
			onPaginationChange: _onPaginationChange,
			onColumnPinningChange: _onColumnPinningChange,
			onColumnOrderChange: _onColumnOrderChange,
			initialState,
			pageCount = -1,
			defaultColumn,
			enableRowSelection = true,
			manualFiltering = false,
			manualPagination = false,
			manualSorting = false,
			...tableOptions
		} = options;

		const resolvedOptions: TableOptionsResolved<TData> = {
			...tableOptions,
			data: this.#resolveData(),
			columns: this.#resolveColumns(),
			initialState,
			// `-1` is the documented "unknown" default. table-core reads `options.pageCount ?? …`,
			// so it has to be handed `undefined` — passing `-1` through would make `getPageCount()`
			// answer `-1` forever and disable every paging control (Divergence 4).
			pageCount: pageCount < 0 ? undefined : pageCount,
			enableRowSelection,
			manualFiltering,
			manualPagination,
			manualSorting,
			// Upstream forces `enableColumnFilter: false` on every column, so only the columns that
			// opt in are filterable. `header`/`cell` are explicitly `undefined` so table-core's
			// built-in default templates do not shadow `DataTableFlexRender`'s fallback branch
			// (research D-03).
			defaultColumn: {
				header: undefined,
				cell: undefined,
				...defaultColumn,
				enableColumnFilter: false
			},
			state: {},
			onStateChange: (updater) => {
				this.#restState = functionalUpdate(updater, this.#getState());
			},
			onSortingChange: (updater) => this.#setSorting(updater),
			onColumnFiltersChange: (updater) => this.#setColumnFilters(updater),
			onColumnVisibilityChange: (updater) => this.#setColumnVisibility(updater),
			onRowSelectionChange: (updater) => this.#setRowSelection(updater),
			onPaginationChange: (updater) => this.#setPagination(updater),
			onColumnPinningChange: (updater) => this.#setColumnPinning(updater),
			onColumnOrderChange: (updater) => this.#setColumnOrder(updater),
			renderFallbackValue: null,
			getCoreRowModel: getCoreRowModel(),
			getFilteredRowModel: getFilteredRowModel(),
			getPaginationRowModel: getPaginationRowModel(),
			getSortedRowModel: getSortedRowModel(),
			getFacetedRowModel: getFacetedRowModel(),
			getFacetedUniqueValues: getFacetedUniqueValues(),
			getFacetedMinMaxValues: getFacetedMinMaxValues()
		};

		const table = createTable(resolvedOptions);
		this.table = table;

		// `table.initialState` is the caller's `initialState` merged with every feature's defaults,
		// so it is the one place that knows the resolved shape of every slice.
		this.sorting = table.initialState.sorting;
		this.columnFilters = table.initialState.columnFilters;
		this.columnVisibility = table.initialState.columnVisibility;
		this.rowSelection = table.initialState.rowSelection;
		this.pagination = table.initialState.pagination;
		this.columnPinning = table.initialState.columnPinning;
		this.columnOrder = table.initialState.columnOrder;

		Object.defineProperties(table.options, {
			data: { get: () => this.#resolveData(), enumerable: true, configurable: true },
			columns: { get: () => this.#resolveColumns(), enumerable: true, configurable: true },
			state: { get: () => this.#getState(), enumerable: true, configurable: true }
		});
	}

	#resolveData(): TData[] {
		const { data } = this.#options;
		return typeof data === 'function' ? data() : data;
	}

	#resolveColumns(): DataTableColumnDef<TData>[] {
		const { columns } = this.#options;
		return typeof columns === 'function' ? columns() : columns;
	}

	#resolveControlledState(): Partial<TableState> {
		const { state } = this.#options;
		if (state === undefined) return {};
		return typeof state === 'function' ? state() : state;
	}

	#getState(): TableState {
		return {
			...this.table.initialState,
			...this.#restState,
			sorting: this.sorting,
			columnFilters: this.columnFilters,
			columnVisibility: this.columnVisibility,
			rowSelection: this.rowSelection,
			pagination: this.pagination,
			columnPinning: this.columnPinning,
			columnOrder: this.columnOrder,
			...this.#resolveControlledState()
		};
	}

	// Each setter resolves the `Updater<T>` table-core hands it against the current slice, assigns
	// the slice, then calls the caller's `on…Change` with the **resolved next value** — never the
	// updater function (data-model.md § State transitions).

	#setSorting(updater: Updater<SortingState>): void {
		const next = functionalUpdate(updater, this.sorting);
		this.sorting = next;
		this.#options.onSortingChange?.(next);
	}

	#setColumnFilters(updater: Updater<ColumnFiltersState>): void {
		const next = functionalUpdate(updater, this.columnFilters);
		this.columnFilters = next;
		this.#options.onColumnFiltersChange?.(next);
	}

	#setColumnVisibility(updater: Updater<VisibilityState>): void {
		const next = functionalUpdate(updater, this.columnVisibility);
		this.columnVisibility = next;
		this.#options.onColumnVisibilityChange?.(next);
	}

	#setRowSelection(updater: Updater<RowSelectionState>): void {
		const next = functionalUpdate(updater, this.rowSelection);
		this.rowSelection = next;
		this.#options.onRowSelectionChange?.(next);
	}

	#setPagination(updater: Updater<PaginationState>): void {
		const next = functionalUpdate(updater, this.pagination);
		this.pagination = next;
		this.#options.onPaginationChange?.(next);
	}

	#setColumnPinning(updater: Updater<ColumnPinningState>): void {
		const next = functionalUpdate(updater, this.columnPinning);
		this.columnPinning = next;
		this.#options.onColumnPinningChange?.(next);
	}

	#setColumnOrder(updater: Updater<ColumnOrderState>): void {
		const next = functionalUpdate(updater, this.columnOrder);
		this.columnOrder = next;
		this.#options.onColumnOrderChange?.(next);
	}
}

/**
 * Create the table state. Must be called during component initialisation — it creates `$state`.
 *
 * @example
 * ```ts
 * const state = createDataTable({
 * 	data: () => rows,
 * 	columns: () => columns,
 * 	getRowId: (row) => row.id,
 * 	initialState: { sorting: [{ id: 'title', desc: true }] }
 * });
 * ```
 */
export function createDataTable<TData extends RowData>(
	options: CreateDataTableOptions<TData>
): DataTableState<TData> {
	return new DataTableState(options);
}

/** What `<DataTable.Root>` publishes so `Toolbar`, `ViewOptions` and `Pagination` can find it. */
export type DataTableContext<TData extends RowData> = {
	readonly table: Table<TData>;
};

const DATA_TABLE_CONTEXT_KEY = Symbol('data-table');

/** Publish the table instance. Called by `<DataTable.Root>`. */
export function setDataTableContext<TData extends RowData>(
	context: DataTableContext<TData>
): DataTableContext<TData> {
	return setContext(DATA_TABLE_CONTEXT_KEY, context);
}

/** Whether a `<DataTable.Root>` is present above the caller. */
export function hasDataTableContext(): boolean {
	return hasContext(DATA_TABLE_CONTEXT_KEY);
}

/**
 * Read the table published by `<DataTable.Root>`. Only `Toolbar`, `ViewOptions` and `Pagination`
 * call this, and only when their own `table` prop is omitted (plan.md Divergence 9).
 */
export function getDataTableContext<TData extends RowData>(): DataTableContext<TData> {
	if (!hasDataTableContext()) {
		throw new Error(
			'`<DataTable.Toolbar>` must be used within `<DataTable.Root>` or given a `table` prop.'
		);
	}
	return getContext<DataTableContext<TData>>(DATA_TABLE_CONTEXT_KEY);
}

/** One instance per `useDataTableInstance()` call. Resolves `table prop ?? context`. */
export class DataTableInstance<TData extends RowData> {
	#getTable!: () => Table<TData> | undefined;
	#context!: DataTableContext<TData> | undefined;

	readonly current: Table<TData> = $derived(this.#getTable() ?? this.#fallback());

	constructor(
		getTable: () => Table<TData> | undefined,
		context: DataTableContext<TData> | undefined
	) {
		this.#getTable = getTable;
		this.#context = context;
	}

	#fallback(): Table<TData> {
		if (this.#context) return this.#context.table;
		throw new Error(
			'`<DataTable.Toolbar>` must be used within `<DataTable.Root>` or given a `table` prop.'
		);
	}
}

/**
 * Resolve the table a part drives: its own `table` prop when given, otherwise the instance
 * `<DataTable.Root>` published (plan.md Divergence 9). Must be called during component
 * initialisation, and throws immediately when neither source is available.
 */
export function useDataTableInstance<TData extends RowData>(
	getTable: () => Table<TData> | undefined
): DataTableInstance<TData> {
	const context = getTable() === undefined ? getDataTableContext<TData>() : undefined;
	return new DataTableInstance(getTable, context);
}
